globalThis.NeoExampleLanguages={"sources":{"cpp":"// Compiled to WebAssembly before publication. Runs inside your browser.\n// The host reads HTTP/RBH1 and supplies x, y, z (metres), then w, x, y, z.\nextern \"C\" int neo_read_pose(double *values);\nextern \"C\" void neo_write_pose(const double *values);\n\nextern \"C\" int run_step() {\n    double pose[7];\n    if (!neo_read_pose(pose)) return 0;\n    double result[10];\n    for (int i = 0; i < 7; ++i) result[i] = pose[i];\n    for (int i = 0; i < 3; ++i) result[7 + i] = pose[i] * 1000.0;\n    // Host displays metres, w/x/y/z orientation and millimetres.\n    neo_write_pose(result);\n    return 1;\n}\n","rust":"// Compiled to WebAssembly before publication. Runs inside your browser.\n// The host reads the device HTTP stream. No native socket or local service.\n#![no_std]\nuse core::panic::PanicInfo;\n\n#[link(wasm_import_module = \"env\")]\nextern \"C\" {\n    fn neo_read_pose(values: *mut f64) -> i32;\n    fn neo_write_pose(values: *const f64);\n}\n\n#[no_mangle]\npub extern \"C\" fn run_step() -> i32 {\n    let mut pose = [0.0_f64; 7];\n    if unsafe { neo_read_pose(pose.as_mut_ptr()) } == 0 { return 0; }\n    let mut result = [0.0_f64; 10];\n    result[..7].copy_from_slice(&pose);\n    for i in 0..3 { result[7 + i] = pose[i] * 1000.0; }\n    unsafe { neo_write_pose(result.as_ptr()); }\n    1\n}\n\n#[panic_handler]\nfn panic(_: &PanicInfo) -> ! { loop {} }\n","python":"import json\n\n# The browser reads HTTP/RBH1 and passes one real device message.\n# This function runs in Python (Pyodide), in a browser worker.\ndef receive(raw):\n    data = json.loads(raw)\n    pose = data[\"pose\"]\n    p, q = pose[\"position\"], pose[\"orientation\"]\n    position = [p[\"x\"], p[\"y\"], p[\"z\"]]\n    result = {\n        \"position_m\": position,\n        \"quaternion_wxyz\": [q[\"w\"], q[\"x\"], q[\"y\"], q[\"z\"]],\n        \"position_mm\": [value * 1000 for value in position],\n    }\n    text = json.dumps(result, ensure_ascii=False)\n    print(text)\n    return text\n"},"source_hashes":{"cpp":"e7bee1391ca75da67d2617c56195e20d99a9881acf833979b916e195971bcc3c","rust":"fbaffe5135cfd07566855e0dfda4bf67db2ae79cb8c5d0b4386e55c5c2ead95c","python":"768bdedfa83946104d61902c255f7a3b064e4460563f051f6df514ce09d6ff08"},"wasm":{"cpp":"","rust":""},"wasm_hashes":{"cpp":"52b2cefe5672d4250f6bd8606c7b1d2b2b625369a0efb2ca7187d4d881157b90","rust":"85800ef888afa0b9d5d5985f41ee5b206981c578963ce50471fc1d476d6e38a9"},"compilers":{"cpp":"clang version 10.0.0-4ubuntu1 ","rust":"rustc 1.83.0 (90b35a623 2024-11-26)"}};
